func (c *Client) applyEditors(ctx context.Context, req *http.Request, additionalEditors []RequestEditorFn) error {
	for _, r := range c.RequestEditors {
		if err := r(ctx, req); err != nil {
			return err
		}
	}
	for _, r := range additionalEditors {
		if err := r(ctx, req); err != nil {
			return err
		}
	}
	return nil
}

// ClientWithResponses builds on ClientInterface to offer response payloads
type ClientWithResponses struct {
	ClientInterface
}

// NewClientWithResponses creates a new ClientWithResponses, which wraps
// Client with return type handling
func NewClientWithResponses(server string, opts ...ClientOption) (*ClientWithResponses, error) {
	client, err := NewClient(server, opts...)
	if err != nil {
		return nil, err
	}
	return &ClientWithResponses{client}, nil
}

// WithBaseURL overrides the baseURL.
func WithBaseURL(baseURL string) ClientOption {
	return func(c *Client) error {
		newBaseURL, err := url.Parse(baseURL)
		if err != nil {
			return err
		}
		c.Server = newBaseURL.String()
		return nil
	}
}

// ClientWithResponsesInterface is the interface specification for the client with responses above.
type ClientWithResponsesInterface interface {

	// GetAncestryWithResponse Walk an image's ancestry to its root base
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/ancestry (the `GetAncestry` operationId).
	GetAncestryWithResponse(ctx context.Context, params *GetAncestryParams, reqEditors ...RequestEditorFn) (*GetAncestryResponse, error)

	// GetCleanupWithResponse Images safe to delete and the storage deleting them frees
	//
	// Deletion candidates: images matching `where` (abandoned ones by
	// default), whole multi-platform indexes only, leaving out any a kept
	// image is built on. `reclaimable_bytes` counts each layer once and
	// only when no kept image uses it. `format=csv` exports every
	// candidate.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/cleanup (the `GetCleanup` operationId).
	GetCleanupWithResponse(ctx context.Context, params *GetCleanupParams, reqEditors ...RequestEditorFn) (*GetCleanupResponse, error)

	// GetLifecyclesWithResponse ECR lifecycle policies that expire what strata calls abandoned
	//
	// One policy per repo expiring untagged images pushed more than the
	// staleness policy's abandoned window ago, checked against the index.
	// A repo where the rule would expire an image strata keeps gets no
	// policy unless `include_conflicts` is set.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/cleanup/lifecycle (the `GetLifecycles` operationId).
	GetLifecyclesWithResponse(ctx context.Context, params *GetLifecyclesParams, reqEditors ...RequestEditorFn) (*GetLifecyclesResponse, error)

	// GetDescendantsWithResponse Find everything built on a base
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/descendants (the `GetDescendants` operationId).
	GetDescendantsWithResponse(ctx context.Context, params *GetDescendantsParams, reqEditors ...RequestEditorFn) (*GetDescendantsResponse, error)

	// GetHealthWithResponse Report server health and index size
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/healthz (the `GetHealth` operationId).
	GetHealthWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetHealthResponse, error)

	// GetImageWithResponse Explain one image
	//
	// Labels, config, layers, referrers, lineage with provenance and the staleness verdict with reasons.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/images/{digest} (the `GetImage` operationId).
	GetImageWithResponse(ctx context.Context, digest string, params *GetImageParams, reqEditors ...RequestEditorFn) (*GetImageResponse, error)

	// GetMapWithResponse Aggregated registry map
	//
	// Root bases and up to three levels below them, leaf images grouped by repo, capped to stay drawable at any registry size.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/map (the `GetMap` operationId).
	GetMapWithResponse(ctx context.Context, params *GetMapParams, reqEditors ...RequestEditorFn) (*GetMapResponse, error)

	// GetOutlineWithResponse One level of the lineage outline
	//
	// Children of an outline node. With no parent, the root bases. Children
	// with descendants come back as base rows; leaf images are grouped into
	// one row per repo, and a repo row's children are its images, paged.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/outline (the `GetOutline` operationId).
	GetOutlineWithResponse(ctx context.Context, params *GetOutlineParams, reqEditors ...RequestEditorFn) (*GetOutlineResponse, error)

	// GetOverviewWithResponse Registry overview for the web UI
	//
	// Headline counts, the staleness mix, the root bases holding the most stale images, and changes in the last week.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/overview (the `GetOverview` operationId).
	GetOverviewWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetOverviewResponse, error)

	// RunQueryWithResponse Filter images with the query language
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/query (the `RunQuery` operationId).
	RunQueryWithResponse(ctx context.Context, params *RunQueryParams, reqEditors ...RequestEditorFn) (*RunQueryResponse, error)

	// GetQueryGraphWithResponse Draw the images a filter matches plus their ancestry
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/query/graph (the `GetQueryGraph` operationId).
	GetQueryGraphWithResponse(ctx context.Context, params *GetQueryGraphParams, reqEditors ...RequestEditorFn) (*GetQueryGraphResponse, error)

	// ResolveRefWithResponse Resolve a ref to a platform manifest digest
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/resolve (the `ResolveRef` operationId).
	ResolveRefWithResponse(ctx context.Context, params *ResolveRefParams, reqEditors ...RequestEditorFn) (*ResolveRefResponse, error)

	// GetRootsWithResponse List root bases and their descendant counts
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/roots (the `GetRoots` operationId).
	GetRootsWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetRootsResponse, error)

	// SearchWithResponse Filter images with facet counts
	//
	// Runs a filter, applies the selected facet values, and returns one page
	// of images plus counts for every facet. Each facet's counts apply every
	// selection except its own, so choosing a value never hides the others.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/search (the `Search` operationId).
	SearchWithResponse(ctx context.Context, params *SearchParams, reqEditors ...RequestEditorFn) (*SearchResponse, error)

	// GetStaleWithResponse Report the staleness mix
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/stale (the `GetStale` operationId).
	GetStaleWithResponse(ctx context.Context, params *GetStaleParams, reqEditors ...RequestEditorFn) (*GetStaleResponse, error)

	// GetStatusWithResponse Progress of the running index
	//
	// Whether `strata serve` is crawling, how far it has got, and when the
	// views were last refreshed. While a long crawl runs, the other UI
	// endpoints answer from what is indexed so far.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/status (the `GetStatus` operationId).
	GetStatusWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetStatusResponse, error)

	// GetSummaryWithResponse Footprint summary of the registry
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/summary (the `GetSummary` operationId).
	GetSummaryWithResponse(ctx context.Context, params *GetSummaryParams, reqEditors ...RequestEditorFn) (*GetSummaryResponse, error)

	// GetVulnBasesWithResponse Rank the bases that carry the most vulnerabilities to the most images
	//
	// Base images whose registry scan found vulnerabilities and that other
	// images are built on, ranked by findings times images in use, then
	// times images.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/vulns/bases (the `GetVulnBases` operationId).
	GetVulnBasesWithResponse(ctx context.Context, params *GetVulnBasesParams, reqEditors ...RequestEditorFn) (*GetVulnBasesResponse, error)

	// GetVulnImpactWithResponse Everything a vulnerable base or a vulnerability reaches
	//
	// Name a base (`ref`) to list every image built on it, or a
	// vulnerability id (`cve`) to list every image whose scan found it
	// plus unscanned images built on one of them. Images are totalled per
	// group (label.team by default). `format=csv` exports every image.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /v1/vulns/impact (the `GetVulnImpact` operationId).
	GetVulnImpactWithResponse(ctx context.Context, params *GetVulnImpactParams, reqEditors ...RequestEditorFn) (*GetVulnImpactResponse, error)
}

